package ru.truetv.launcher;
import android.app.*;
import android.accessibilityservice.*;
import android.content.*;
import android.os.*;
import android.preference.*;
import android.view.*;
import android.view.accessibility.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
/** New defaults and requested menus on real windows; no shutdown, firmware write or grant. */
public final class DefaultsActionsCheck extends Instrumentation {
 private StatusWatch.Listener idleSink;private Context c;private HomeActivity home;private int checks;private final StringBuilder out=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean v,String msg){checks++;out.append(v?"PASS ":"FAIL ").append(msg).append('\n');if(!v)throw new AssertionError(msg);}
 private void main(Runnable r){Throwable[] t={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){t[0]=e;}});waitForIdleSync();if(t[0]!=null)throw new AssertionError(t[0]);}
 private Object field(Object o,String name){try{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new AssertionError(e);}}
 private ActionSheet sheet(){try{Field f=ActionSheet.class.getDeclaredField("active");f.setAccessible(true);return ((java.lang.ref.WeakReference<ActionSheet>)f.get(null)).get();}catch(Exception e){throw new AssertionError(e);}}
 private String row(ActionSheet s,int i){return ((TextView)((ViewGroup)((ViewGroup)s.rows.get(i)).getChildAt(1)).getChildAt(0)).getText().toString();}
 private <T extends Activity>T open(Class<T> cls,Runnable action){ActivityMonitor m=new ActivityMonitor(cls.getName(),null,false);addMonitor(m);main(action);Activity a=waitForMonitorWithTimeout(m,15000);removeMonitor(m);if(a==null)throw new AssertionError("Missing "+cls);return (T)a;}
 private void shot(String name)throws Exception{VmWindows.ready(this);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(c.getExternalFilesDir(null),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 private void idleStatusCheck()throws Exception{
  java.util.concurrent.atomic.AtomicInteger queries=new java.util.concurrent.atomic.AtomicInteger(),callbacks=new java.util.concurrent.atomic.AtomicInteger(),visible=new java.util.concurrent.atomic.AtomicInteger();
  Context fake=new ContextWrapper(c){public Context getApplicationContext(){return this;}public Object getSystemService(String name){queries.incrementAndGet();return null;}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f){throw new SecurityException("No OS event fixture");}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f,int flags){throw new SecurityException("No OS event fixture");}};
  idleSink=new StatusWatch.Listener(){public java.util.List<String> visiblePackages(){visible.incrementAndGet();return java.util.Collections.emptyList();}public void status(boolean v,String o,int b,java.util.Set<String> live){callbacks.incrementAndGet();}};
  StatusWatch watch=new StatusWatch(fake,idleSink);try{main(watch::start);long until=SystemClock.uptimeMillis()+5000;while(callbacks.get()==0&&SystemClock.uptimeMillis()<until)Thread.sleep(40);check(callbacks.get()==1,"initial status snapshot delivered");int initial=queries.get();Thread.sleep(4200);check(queries.get()==initial&&callbacks.get()==1,"default status has no repeated idle polling");check(visible.get()==0,"running dots off skips visible-package scanning");}finally{main(watch::stop);idleSink=null;}
 }
 private void change(Preference p,Object value){try{Method m=Preference.class.getDeclaredMethod("callChangeListener",Object.class);m.setAccessible(true);if(Boolean.TRUE.equals(m.invoke(p,value))){if(p instanceof ListPreference)((ListPreference)p).setValue(String.valueOf(value));else ((CheckBoxPreference)p).setChecked(Boolean.TRUE.equals(value));}}catch(Exception e){throw new AssertionError(e);}}
 public void onStart(){Bundle result=new Bundle();SettingsActivity settings=null;AccessActivity access=null;ExpertActivity expert=null;try{
  c=getTargetContext();check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"disposable VM only");VmWindows.prepare(this);SettingsStore store=new SettingsStore(c);store.data.edit().clear().putBoolean("bt_asked",true).commit();
  check(Ui.theme(c).equals("black"),"fresh theme black");check(store.columns()==5&&store.rows()==4,"fresh grid5x4");check(store.number("icon",1)==0&&!store.flag("labels",true)&&!store.flag("borders",true),"automatic icons; labels and normal borders off");check(store.number("opacity",10)==0&&!store.flag("wallpaper",true)&&!store.flag("keep_awake",true),"zero opacity; wallpaper and keep-awake off");check(store.text("clock_font","").equals("medium")&&store.text("date_format","").equals("numeric"),"clear clock and numeric date");check(store.number("menu_icon",64)==56&&store.flag("show_self",false),"menu56 and launcher shown");check(store.flag("bt_count",false)&&!store.flag("running",true)&&store.flag("extended_menu_first",false),"Bluetooth on, running off, close/restart first");
  idleStatusCheck();home=VmWindows.home(this);check(home.board.getChildCount()==20,"actual desktop has20 slots");check(((android.graphics.drawable.ColorDrawable)((ViewGroup)home.findViewById(android.R.id.content)).getChildAt(0).getBackground()).getColor()==0xff000000,"actual black desktop canvas");shot("home220-defaults.png");
  settings=open(SettingsActivity.class,()->home.header.getChildAt(3).performClick());final SettingsActivity page=settings;check(((ListPreference)settings.findPreference("rows")).getValue().equals("4"),"native rows preference4");check(((ListPreference)settings.findPreference("theme")).getValue().equals("black"),"native theme preferenceblack");check(!((CheckBoxPreference)settings.findPreference("labels")).isChecked()&&!((CheckBoxPreference)settings.findPreference("borders")).isChecked(),"native labels/borders unchecked");check(((CheckBoxPreference)settings.findPreference("extended_menu_first")).isChecked(),"native close/restart checkbox checked");check(settings.findPreference("about").getSummary().toString().contains(BuildConfig.VERSION_NAME),"About always contains actual version");check(settings.findPreference("restricted").getTitle().toString().equals(Ui.word(c,"Снять ограничение доступа к специальным возможностям","Remove Accessibility access restriction")),"restricted row renamed precisely");check(settings.findPreference("volume_hold")!=null&&settings.findPreference("volume_hold").getOrder()>settings.findPreference("restricted").getOrder(),"volume restoration is directly below restricted-access action");shot("settings220-defaults.png");
  main(()->{change(page.findPreference("rows"),"2");change(page.findPreference("labels"),true);change(page.findPreference("menu_icon"),"80");});main(settings::finish);settings=null;check(home.board.getChildCount()==10,"actual layout setting change rebuilds to5x2");settings=open(SettingsActivity.class,()->home.header.getChildAt(3).performClick());check(((ListPreference)settings.findPreference("rows")).getValue().equals("2")&&((CheckBoxPreference)settings.findPreference("labels")).isChecked()&&((ListPreference)settings.findPreference("menu_icon")).getValue().equals("80"),"opening settings/update preserves existing explicit choices");main(settings::finish);settings=null;
  access=open(AccessActivity.class,()->Controls.restricted(home));LinearLayout buttons=(LinearLayout)((ViewGroup)((ViewGroup)access.findViewById(android.R.id.content)).getChildAt(0)).getChildAt(2);String[] labels={Ui.word(c,"Включить через ADB","Enable through ADB"),Ui.word(c,"Подключение ADB","ADB connection"),Ui.word(c,"Снять для выбранных","Allow selected apps"),Ui.word(c,"Специальные возможности","Accessibility settings")};check(buttons.getChildCount()==4,"exactly four TV Access buttons");for(int i=0;i<4;i++)check(((Button)buttons.getChildAt(i)).getText().toString().startsWith(labels[i]),"TV Access button order "+i);check(!(Boolean)field(access,"busy"),"opening/reordering helper does not connect or run a grant");shot("access220-order.png");main(access::finish);access=null;
  main(()->Controls.powerSheet(home));ActionSheet power=sheet();check(power.rows.size()==3,"two power commands plus Cancel; no Sleep or Accessibility row");check(row(power,0).equals(Ui.word(c,"Выключить","Power off"))&&row(power,1).equals(Ui.word(c,"Перезагрузить","Restart")),"power off and restart are separate commands");check(!Controls.ready(c),"service initially not granted");for(int i=0;i<2;i++){TextView note=(TextView)((ViewGroup)((ViewGroup)power.rows.get(i)).getChildAt(1)).getChildAt(1);check(note.getVisibility()==View.VISIBLE&&note.getText().toString().contains("True TV Launcher"),"grey command has inline own-settings hint "+i);}shot("power220-unavailable.png");ActivityMonitor grant=new ActivityMonitor(new IntentFilter("android.settings.ACCESSIBILITY_SETTINGS"),null,true);addMonitor(grant);main(()->power.rows.get(0).performClick());check(grant.getHits()==0&&!Controls.ready(c),"grey power click neither opens Accessibility nor grants it");removeMonitor(grant);
  expert=open(ExpertActivity.class,()->home.startActivity(new Intent(home,ExpertActivity.class)));final ExpertActivity manager=expert;Method actions=ExpertActivity.class.getDeclaredMethod("actions",ExpertActivity.Entry.class);actions.setAccessible(true);main(()->{try{actions.invoke(manager,new ExpertActivity.Entry("ru.truetv.probe","Removed system fixture",null,false,false));}catch(Exception e){throw new AssertionError(e);}});ActionSheet removed=sheet();check(row(removed,0).equals(Ui.word(c,"Восстановить установки","Restore installations")),"removed package retains restore option");check(row(removed,1).contains(Ui.word(c,"Физически удалить","Physically delete")),"physical deletion remains offered after profile uninstall");main(removed.dialog::dismiss);main(expert::finish);expert=null;
  check(getUiAutomation().performGlobalAction(AccessibilityService.GLOBAL_ACTION_POWER_DIALOG),"VM public system power dialog opens");boolean found=false;long end=SystemClock.uptimeMillis()+8000;while(!found&&SystemClock.uptimeMillis()<end){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null){if(PowerChoice.trusted(String.valueOf(root.getPackageName()))){ArrayList<AccessibilityNodeInfo> nodes=new ArrayList<>();ControlService.collect(root,nodes,0);boolean off=false,reboot=false,known=false;for(AccessibilityNodeInfo n:nodes){off|=PowerChoice.action(String.valueOf(n.getText()),false)||PowerChoice.action(String.valueOf(n.getContentDescription()),false);reboot|=PowerChoice.action(String.valueOf(n.getText()),true)||PowerChoice.action(String.valueOf(n.getContentDescription()),true);known|=PowerChoice.menuId(n.getViewIdResourceName());}found=off&&reboot&&PowerChoice.menu(off,reboot,known);for(AccessibilityNodeInfo n:nodes)n.recycle();}else root.recycle();}if(!found)Thread.sleep(100);}check(found,"exact power off/restart choices recognized in actual system UI (no activation)");getUiAutomation().performGlobalAction(AccessibilityService.GLOBAL_ACTION_BACK);
  result.putBoolean("passed",true);result.putString("report",out+"Checks="+checks+"; no firmware mutation or actual shutdown/reboot tested");
 }catch(Throwable t){StringWriter s=new StringWriter();t.printStackTrace(new PrintWriter(s));result.putBoolean("passed",false);result.putString("report",out+s.toString());}finally{try{if(settings!=null)main(settings::finish);if(access!=null)main(access::finish);if(expert!=null)main(expert::finish);}catch(Exception ignored){}}finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
